dding=\"0\" cellspacing=\"0\" width=\"600\" style=\"max-width: 600px; background-color: #ffffff; border-radius: 16px; border: 1px solid #e2e8f0; box-shadow: 0 10px 25px -5px rgba(15, 23, 42, 0.08), 0 8px 10px -6px rgba(15, 23, 42, 0.04); overflow: hidden;\">\n          \n          <!-- Brand Header with Logo -->\n          <tr>\n            <td align=\"center\" style=\"padding: 32px 32px 20px 32px; background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%); border-bottom: 1px solid #f1f5f9;\">\n              <a href=\"{{ResetLink}}\" target=\"_blank\" style=\"text-decoration: none; display: inline-block;\">\n                <img src=\"{{LogoUrl}}\" alt=\"Print My 3D\" width=\"160\" height=\"42\" style=\"display: block; max-width: 180px; height: auto; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; font-size: 22px; font-weight: 800; color: #133827; letter-spacing: -0.5px;\" />\n              </a>\n            </td>\n          </tr>\n\n          <!-- Status Badge & Greeting Section -->\n          <tr>\n            <td class=\"mobile-p-20 mobile-pt-24\" style=\"padding: 32px 40px 16px 40px; text-align: center;\">\n              \n              <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" align=\"center\" style=\"margin: 0 auto 16px auto;\">\n                <tr>\n                  <td style=\"background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 9999px; padding: 6px 16px; text-align: center;\">\n                    <span style=\"font-size: 12px; font-weight: 700; color: #334155; text-transform: uppercase; letter-spacing: 0.8px;\">\n                      Beveiliging &bull; Account\n                    </span>\n                  </td>\n                </tr>\n              </table>\n              <h1 style=\"margin: 0 0 12px 0; font-size: 24px; line-height: 32px; font-weight: 800; color: #0f172a; letter-spacing: -0.5px;\">\n                Wachtwoord Opnieuw Instellen\n              </h1>\n              <p style=\"margin: 0; font-size: 15px; line-height: 24px; color: #475569;\">\n                Hallo <strong>{{CustomerName}}</strong>, we hebben een verzoek ontvangen om je wachtwoord opnieuw in te stellen. Klik op de onderstaande knop om een nieuw wachtwoord te kiezen. Als je dit niet hebt aangevraagd, kun je deze e-mail veilig negeren.\n              </p>\n            </td>\n          </tr>\n\n          \n\n          \n\n          <!-- Action Area (CTA) -->\n          <tr>\n            <td class=\"mobile-p-20\" style=\"padding: 12px 40px 32px 40px; text-align: center;\">\n                <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"max-width: 440px; margin: 0 auto;\">\n    <tr>\n      <td align=\"center\" style=\"border-radius: 10px; background-color: #133827; box-shadow: 0 4px 14px rgba(19, 56, 39, 0.35);\">\n        <a href=\"{{ResetLink}}\" target=\"_blank\" style=\"display: block; padding: 18px 36px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; font-size: 16px; font-weight: 700; color: #ffffff; text-decoration: none; border-radius: 10px; letter-spacing: 0.3px; border: 1px solid #1c4f37; text-align: center;\">\n          Wachtwoord Opnieuw Instellen &rarr;\n        </a>\n      </td>\n    </tr>\n  </table>\n                <p style=\"margin: 14px 0 0 0; font-size: 12px; line-height: 18px; color: #94a3b8; text-align: center;\">\n    Deze link voor het opnieuw instellen van je wachtwoord verloopt over 2 uur. Als je dit niet hebt aangevraagd, is er geen actie vereist.\n  </p>\n            </td>\n          </tr>\n\n          <!-- Footer -->\n          <tr>\n            <td style=\"padding: 24px 32px; background-color: #f8fafc; border-top: 1px solid #e2e8f0; text-align: center;\">\n              <p style=\"margin: 0 0 6px 0; font-size: 13px; font-weight: 600; color: #475569;\">\n                Vragen over je account of wachtwoord?\n              </p>\n              <p style=\"margin: 0 0 14px 0; font-size: 12px; color: #64748b; line-height: 18px;\">\n                Neem contact op met ons team via <a href=\"mailto:info@printmy3d.work\" style=\"color: #0f766e; text-decoration: none; font-weight: 600;\">info@printmy3d.work</a>.\n              </p>\n              <p style=\"margin: 0; font-size: 11px; color: #94a3b8; line-height: 16px;\">\n                &copy; Print My 3D &bull; Precisie Additive Manufacturing &bull; Rotterdam, NL\n              </p>\n            </td>\n          </tr>\n\n        </table>\n      </td>\n    </tr>\n  </table>\n</body>\n</html>", "nl", "Stel je PrintCraft wachtwoord opnieuw in", "ResetPassword" },
